/*
 * Page generated by ChannelPreviewFrameFilter: the previewed page inside the frame of a device.
 *
 * On a phone or a tablet, scrollbars are drawn over the page and take no room. On a computer they may take room,
 * which makes the previewed page narrower than the screen of the device. For the devices that declare the capability
 * "overlay-scrollbars", this script hides the scrollbar of the previewed page, which stays scrollable with the wheel,
 * the keyboard and touch. It never moves the focus.
 */
(function () {
    var STYLE_ID = 'channels-overlay-scrollbars';
    var STYLE = 'html{scrollbar-width:none}html::-webkit-scrollbar{display:none}';

    function hideScrollbar(screen) {
        try {
            var page = screen.contentDocument;
            if (!page || !page.head || page.getElementById(STYLE_ID)) {
                return;
            }
            var style = page.createElement('style');
            style.id = STYLE_ID;
            style.textContent = STYLE;
            page.head.appendChild(style);
        } catch (e) {
            // the page of another origin cannot be reached: its scrollbar stays visible
        }
    }

    // jContent shows this page in a frame that keeps the default border of the browser, which draws lines around the
    // device: it is removed. Only the frame of the jContent customized preview is changed.
    try {
        var host = window.frameElement;
        if (host && host.getAttribute('data-sel-role') === 'customized-preview-iframe') {
            host.style.border = '0';
        }
    } catch (e) {
        // the page is not shown by jContent, or by another origin
    }

    var screens = document.querySelectorAll('iframe[data-overlay-scrollbars]');
    Array.prototype.forEach.call(screens, function (screen) {
        // again after each navigation inside the screen
        screen.addEventListener('load', function () {
            hideScrollbar(screen);
        });
        hideScrollbar(screen);
    });
})();
